var InkTools={
 size:32,last:null,paths:new WeakMap(),boundsCache:new WeakMap(),
 init(){const canvas=$('#canvas');canvas.addEventListener('pointerdown',e=>{if(tool!=='eraser'||spacePressed||e.button!==0||e.target.closest('.canvas-bottom,.tool-options,#selectionActions,button,input,textarea,[contenteditable]'))return;e.preventDefault();e.stopImmediatePropagation();checkpoint();CanvasSelection.one(null);const p=scenePoint(e);drag={type:'erase',trace:[[p.x,p.y]],radius:this.size/(2*zoom),last:p};this.eraseAt(p);renderInk();canvas.setPointerCapture?.(e.pointerId)},true);
  document.addEventListener('pointermove',e=>{if(drag?.type!=='erase')return;e.preventDefault();const p=scenePoint(e),old=drag.last,steps=Math.max(1,Math.ceil(Math.hypot(p.x-old.x,p.y-old.y)/Math.max(1,drag.radius*.5)));for(let i=1;i<=steps;i++)this.eraseAt({x:old.x+(p.x-old.x)*i/steps,y:old.y+(p.y-old.y)*i/steps});drag.trace.push([p.x,p.y]);drag.last=p;renderInk()});
 },
 bounds(stroke){const points=stroke.points,first=points[0]||[0,0],last=points.at(-1)||first,key=[points.length,...first,...last].join(','),cached=this.boundsCache.get(stroke);if(cached&&cached.points===points&&cached.key===key)return cached;let left=Infinity,top=Infinity,right=-Infinity,bottom=-Infinity;for(const p of points){left=Math.min(left,p[0]);top=Math.min(top,p[1]);right=Math.max(right,p[0]);bottom=Math.max(bottom,p[1])}const result={points,key,left,top,right,bottom};this.boundsCache.set(stroke,result);return result},
 eraseAt(p){const d=drag;if(d?.type!=='erase')return;const next=[];for(const stroke of board().strokes){if(!stroke.id)stroke.id=uid();const r=d.radius+(stroke.size||3)/2,b=this.bounds(stroke);if(b.right<p.x-r||b.left>p.x+r||b.bottom<p.y-r||b.top>p.y+r){next.push(stroke);continue}const pieces=InkGeometry.erase(stroke.points,{...p,r});if(pieces.length===1&&pieces[0]===stroke.points){next.push(stroke);continue}for(let i=0;i<pieces.length;i++)if(pieces[i].length>1)next.push({...stroke,id:i===0?stroke.id:uid(),points:pieces[i]})}board().strokes=next},
 paintStroke(stroke){let entry=this.paths.get(stroke);if(!entry||!entry.hit.isConnected||entry.count>stroke.points.length){const hit=$('#inkLayer').querySelector('[data-stroke="'+CSS.escape(stroke.id)+'"]');if(!hit){renderInk();return this.paintStroke(stroke)}entry={hit,path:hit.previousElementSibling,count:0,d:''};this.paths.set(stroke,entry)}for(let i=entry.count;i<stroke.points.length;i++){const p=stroke.points[i];entry.d+=(i?'L':'M')+p[0]+' '+p[1]+' '}entry.count=stroke.points.length;entry.path.setAttribute('d',entry.d);entry.hit.setAttribute('d',entry.d)},
 options(){const box=$('#toolOptions');box.innerHTML='<div class="eraser-options"><strong>Erase drawings</strong><input id="eraserSize" type="range" min="8" max="120" step="2" value="'+this.size+'" aria-label="Eraser size"><output id="eraserSizeValue">'+this.size+' px</output><span>Drag to erase · Ctrl Z to undo</span></div>';$('#eraserSize').oninput=e=>{this.size=Number(e.target.value);$('#eraserSizeValue').textContent=this.size+' px'}}
};
